// The course name, in English and Spanish, and its author(s), for every course
// certificate page, for the downloadable PDF certificate
// (public/assets/js/cts-cert-pdf.js).
//
//   node tools/build-cert-names.mjs          write public/assets/js/cts-cert-names.js
//   node tools/build-cert-names.mjs --check  fail if that file is out of date
//
// Names and authors come from the seminary's Certificate Maker, copied into
// src/data/certificate-courses.json (Dr. Cook, 29 Sept 2026: "make the Spanish
// course names generated by the certificates match the names in the current
// Certificate Maker"), so a PDF from the site and one from the office match. A
// course the Maker does not list (Counseling Situations) takes the catalog's
// name (src/content/courses) and Dr. Cook as author.
// A certificate page is matched to its course by filename: CTSActsCertificate,
// CTSActsMDivCertificate and CTSActsThMCertificate are all Acts. The few pages
// whose filename does not follow the course's are listed below.
import fs from 'node:fs';
import path from 'node:path';

const OUT = 'public/assets/js/cts-cert-names.js';
const DEGREES = new Set(['ctsmdivcertificate.html', 'ctsthmcertificate.html',
  'ctsassociatecertificate.html', 'ctscertificateofministry.html']);
const ODD = {                       // certificate page base -> catalog file
  CTSOTS: 'CTS',
  CTSNarrativePreaching: 'CTS_Narrative_Preaching',
  CTSPreaching: 'CTS_WiseSpeak_Preaching',
  ethics_certificate: 'ethics_unit01',
};

const MAKER = JSON.parse(fs.readFileSync('src/data/certificate-courses.json', 'utf8')).courses;
const byCatalog = {};
for (const c of Object.values(MAKER)) if (c.catalog) byCatalog[c.catalog] = c;

const courses = {};
for (const f of fs.readdirSync('src/content/courses')) {
  courses[f.replace(/\.json$/, '')] = JSON.parse(fs.readFileSync(path.join('src/content/courses', f), 'utf8'));
}

const names = {};
const problems = [];
for (const f of fs.readdirSync('public').filter((f) => /certificate/i.test(f) && f.endsWith('.html')).sort()) {
  if (DEGREES.has(f.toLowerCase())) continue;
  const base = f === 'ethics_certificate.html' ? 'ethics_certificate' : f.replace(/(MDiv|ThM)?Certificate\.html$/, '');
  const key = ODD[base] || base;
  const c = courses[key];
  if (!c) { problems.push(`${f}: no catalog entry for "${base}"`); continue; }
  const m = byCatalog[key];
  names[f.toLowerCase()] = m ? { en: m.en, es: m.es, authors: m.authors } : { en: c.title.en, es: c.title.es, authors: ['cook'] };
}
if (problems.length) { problems.forEach((p) => console.error('  ' + p)); process.exit(1); }

// Every course by its completion code, for the diploma pages' lists of the
// courses that count (cts-degrees.js counts by code, and names them from this).
const cat = JSON.parse(fs.readFileSync('worker/catalog.json', 'utf8'));
const byCode = {};
for (const [code, c] of Object.entries(cat.completions)) {
  const slug = Object.keys(cat.courses).find((k) => cat.courses[k].code === code);
  const single = { WISESPEAK: 'wisespeak', COUNSELING: 'counseling', STORYTEL: 'narrative', ETHICS: 'ethics' }[code];
  const m = MAKER[slug] || MAKER[single];
  const fallback = Object.values(courses).find((x) => (x.code || '').toUpperCase() === code || `CTS${(x.code || '').toUpperCase().replace(/^CTS/, '')}` === code);
  byCode[code] = m ? { en: m.en, es: m.es }
    : fallback ? { en: fallback.title.en, es: fallback.title.es }
    : { en: c.name.replace(/\s*\|\s*$/, ''), es: c.name.replace(/\s*\|\s*$/, '') };
}

const text = '/* The course name on each course certificate, English and Spanish, and its\n' +
  '   author(s), for the downloadable PDF (cts-cert-pdf.js). Written by\n' +
  '   tools/build-cert-names.mjs from src/data/certificate-courses.json (the\n' +
  '   Certificate Maker\'s list) -- change that and re-run it. */\n' +
  'window.CTS_CERT_NAMES = ' + JSON.stringify(names, null, 1) + ';\n' +
  '/* Every course by completion code, for the diploma pages (cts-degrees.js). */\n' +
  'window.CTS_COURSE_NAMES = ' + JSON.stringify(byCode, null, 1) + ';\n';

if (process.argv.includes('--check')) {
  const now = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (now !== text) { console.error(`${OUT} is out of date — run: node tools/build-cert-names.mjs`); process.exit(1); }
  console.log(`${OUT}: ${Object.keys(names).length} certificate pages, up to date`);
} else {
  fs.writeFileSync(OUT, text);
  console.log(`wrote ${Object.keys(names).length} certificate pages to ${OUT}`);
}
